window.AUTH=window.AUTH||{};window.AUTH["18-15"]={"d":"18-15","id":"2018/18-15","n":"Kisor v. Wilkie","briefs":[{"k":"petitioner","label":"Brief of petitioner James L. Kisor","date":"2019-01-24","url":"https://www.supremecourt.gov/DocketPDF/18/18-15/81646/20190124174802189_18-15.brief.pdf","side":"pet","n":78},{"k":"respondent","label":"Brief of respondent Robert Wilkie, Secretary of Veterans Affairs","date":"2019-02-25","url":"https://www.supremecourt.gov/DocketPDF/18/18-15/89588/20190225184823584_18-15bsUnitedStates.pdf","side":"res","n":112},{"k":"reply","label":"Reply of petitioner James L. Kisor","date":"2019-03-14","url":"https://www.supremecourt.gov/DocketPDF/18/18-15/92013/20190314153820889_18-15.rb.pdf","side":"pet","n":36}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/18-15_9p6b.pdf","tr":true,"items":[{"t":"case","label":"Alleyne v. United States","cite":"570 U.S. 99","y":2013,"id":"2012/11-9335","sc":1,"sum":"The Court found that a defendant cannot be found guilty of a claim not included in the indictment.","sumSrc":"Oyez","by":{"0":"49","1":"36"}},{"t":"case","label":"Appalachian Power Co., v. EPA","cite":"208 F.3d 1015","y":2000,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/208/1015/","by":{"0":"54"}},{"t":"case","label":"Auer v. Robbins","cite":"519 U.S. 452","y":1997,"id":"1996/95-897","sc":1,"op":253,"ar":42,"sum":"Authored by Justice Antonin Scalia, the Court ruled that sergeants and lieutenants are exempt as salaried employees from the federal Fair Labor Standards Act. The justices rejected the argument that the possibility of suspension without pay moves the officers out of the exempt category.","sumSrc":"Oyez","by":{"0":"passim","1":"5, 6, 12, 14, 30, 38"}},{"t":"case","label":"Boone v. Lightner","cite":"319 U.S. 561","y":1943,"id":"scdb/1942-138","sc":1,"sum":"Section 201 of the Soldiers' and Sailors' Civil Relief Act of 1940, providing for stays in court proceedings involving persons in military service, addresses to the discretion of the court the question whether \"the ability of... the defendant to conduct his defense is not materially affected by reason of his military service.\" In the circumstances of this case, denial of a stay at the instance of a defendant in …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"60"}},{"t":"case","label":"Bowles v. Seminole Rock & Sand Co.","cite":"325 U.S. 410","y":1945,"id":"scdb/1944-069","sc":1,"op":7,"by":{"0":"3, 6","1":"passim"}},{"t":"case","label":"Bruesewitz v. Wyeth LLC","cite":"562 U.S. 223","y":2011,"id":"2010/09-152","sc":1,"op":1,"sum":"The Court held that the National Childhood Vaccine Injury Act shielded manufacturers from certain product liability lawsuits that seek damages for serious health problems suffered by children.","sumSrc":"Oyez","by":{"0":"42","1":"19"}},{"t":"case","label":"Chase Bank USA, N.A. v. McCoy","cite":"562 U.S. 195","y":2011,"id":"2010/09-329","sc":1,"op":2,"sum":"The Court held that the Truth In Lending Act did not require Chase Bank to provide notice of interest rate increases that occurred because of customer default.","sumSrc":"Oyez","by":{"0":"9","1":"6, 38"}},{"t":"case","label":"Chevron, U.S.A., Inc. v. Natural Res. Def. Council, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"op":16,"ar":6,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"0":"passim","1":"12, 19, 40"}},{"t":"case","label":"Chickaloon-Moose Creek Native Ass’n, Inc. v. Norton","cite":"360 F.3d 972","y":2004,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/360/972/","by":{"0":"40"}},{"t":"case","label":"Christopher v. SmithKline Beecham Corp.","cite":"567 U.S. 142","y":2012,"id":"2011/11-204","sc":1,"op":12,"sum":"Noting for this reason that Auer deference imparts “predictability to the administrative process” (internal quotation marks omitted).","sumSrc":"opinion","by":{"0":"10, 37","1":"27, 30, 31, 38, 40","2":"10"}},{"t":"case","label":"Chrysler Corp. v. Brown","cite":"441 U.S. 281","y":1979,"id":"1978/77-922","sc":1,"op":1,"ar":1,"sum":"Petitioner, as a party to numerous Government contracts, was required to comply with Executive Orders 11246 and 11375, which charge the Secretary of Labor with ensuring that corporations that benefit from Government contracts provide equal employment opportunity regardless of race or sex. Regulations promulgated by the Department of Labor's Office of Federal Contract Compliance Programs (OFCCP) require Government …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28, 29, 33","1":"23"}},{"t":"case","label":"City of Arlington v. FCC","cite":"569 U.S. 290","y":2013,"id":"2012/11-1545","sc":1,"op":9,"sum":"Noting that “context-specific[ ] factors” may show that “Congress would [not] have intended the agency to resolve [some] ambiguity”.","sumSrc":"opinion","by":{"0":"passim","1":"20, 28, 45","2":"1, 2, 5"}},{"t":"case","label":"Coeur Alaska, Inc. v. Southeast Alaska Conservation Council","cite":"557 U.S. 261","y":2009,"id":"2008/07-984","sc":1,"op":1,"sum":"The Court held that the United States Army Corps of Engineers had exclusive rights to grant a permit to Coeur Alaska, Inc. to discharge its waste.","sumSrc":"Oyez","by":{"0":"9, 29, 32, 51","1":"6"}},{"t":"case","label":"Crawford v. Washington","cite":"541 U.S. 36","y":2004,"id":"2003/02-9410","sc":1,"sum":"The Court sided with Crawford and ruled that the Sixth Amendment's Confrontation Clause gives defendants the right to confront witnesses and cross-examine their testimony. This includes testimony police gather. The Court reasoned that the Framers intended the Confrontation Clause to prohibit out-of-court testimony as evidence against defendants.","sumSrc":"Oyez","by":{"0":"48"}},{"t":"case","label":"Decker v. Northwest Envtl. Def. Ctr.","cite":"568 U.S. 597","y":2013,"id":"2012/11-338","sc":1,"op":5,"sum":"The Court found that based on the Clean Water Act, a permit is not necessary for storm water runoff because it is not associated with industrial activity.","sumSrc":"Oyez","by":{"0":"passim","1":"22, 29, 30","2":"13"}},{"t":"case","label":"Ehlert v. United States","cite":"402 U.S. 99","y":1971,"id":"1970/120","sc":1,"op":1,"sum":"The refusal of petitioner's local board to reopen his classification and pass on his conscientious objector claim, made after mailing of his induction notice but before induction, on the basis of a Selective Service regulation that permitted post-induction notice reopening only for a \"change in the registrant's status resulting from circumstances over which the registrant had no control,\" held not unreasonable as a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"8","1":"5, 27, 31"}},{"t":"case","label":"Encino Motorcars, LLC v. Navarro","cite":"136 S. Ct. 2117","y":2016,"id":"2015/15-415","sc":1,"sum":"The Court held that, because the Department of Labor did not give adequate reasons for altering its position on whether service advisors are exempt from overtime compensation under the Fair Labor Standards Act (FLSA), the case should be remanded for reinterpretation that does not give controlling weight to the Department’s 2011 position.","sumSrc":"Oyez","by":{"0":"29, 30, 33, 35"}},{"t":"case","label":"FCC v. Fox Television Stations, Inc.","cite":"556 U.S. 502","y":2009,"id":"2008/07-582","sc":1,"op":1,"sum":"The Court held that the FCC's imposition of liability on Fox Television Stations for fleeting expletives was not \"arbitrary and capricious\" under the Administrative Procedure Act, even though the FCC previously accepted similar expletives.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Free Enterprise Fund v. Public Co. Accounting Oversight Bd.","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"op":1,"sum":"The Court held that the Sarbanes-Oxley Act violated the Appointment Clause of the Constitution.","sumSrc":"Oyez","by":{"0":"54","1":"40"}},{"t":"case","label":"Garco Constr., Inc. v. Speer","cite":"138 S. Ct. 1052","y":2018,"url":"https://www.courtlistener.com/c/S.%20Ct./138/1052/","sc":1,"by":{"0":"29, 52"}},{"t":"case","label":"Geier v. American Honda Motor Co.","cite":"529 U.S. 861","y":2000,"id":"1999/98-1811","sc":1,"op":1,"sum":"The Court held that \"[Geier's] 'no airbag' lawsuit conflicts with the objectives of FMVSS 208 and is therefore pre-empted by the Act.\" Justice Breyer wrote for the Court that a rule of state tort law imposing a duty to install airbags in cars such as Honda's would have presented an obstacle to the variety and mix of devices that the federal regulation sought and to the phase-in that the federal regulation deliberately imposed.","sumSrc":"Oyez","by":{"0":"9"}},{"t":"case","label":"Gloucester Cty. Sch. Bd. v. G.G. ex rel. Grimm","cite":"137 S. Ct. 1239","url":"https://www.courtlistener.com/c/S.%20Ct./137/1239/","sc":1,"by":{"0":"39"}},{"t":"case","label":"Gonzales v. Oregon","cite":"546 U.S. 243","y":2006,"id":"2005/04-623","sc":1,"op":2,"ar":1,"sum":"The Court decided that the Controlled Substance Act did not ban the use of controlled substances in physician-assisted suicide, nor does the Attorney General have the power to determine what is a violation of the Act.","sumSrc":"Oyez","by":{"0":"9, 10","1":"33, 34, 42","2":"11"}},{"t":"case","label":"G.G. ex rel. Grimm v. Gloucester Cty. Sch. Bd.","cite":"822 F.3d 709","y":2016,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/822/709/","by":{"0":"39"}},{"t":"case","label":"Henderson v. Shinseki","cite":"562 U.S. 428","y":2011,"id":"2010/09-1036","sc":1,"sum":"The Court held that missing the deadline for filing a notice of appeal with the Veterans Court did not bar a plaintiff from making a claim.","sumSrc":"Oyez","by":{"0":"60","1":"7"}},{"t":"case","label":"Hodge v. West","cite":"155 F.3d 1356","y":1998,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/155/1356/","by":{"0":"60"}},{"t":"case","label":"INS v. Chadha","cite":"462 U.S. 919","y":1983,"id":"1981/80-1832","sc":1,"op":1,"sum":"The Court held that the Immigration and Nationality Act violated the separation of powers by allowing a one-house veto over executive decisions.","sumSrc":"Oyez","by":{"0":"45, 53","1":"45"}},{"t":"case","label":"INS v. Stanisic","cite":"395 U.S. 62","y":1969,"id":"1968/297","sc":1,"op":1,"sum":"Respondent, a Yugoslav crewman, while in the United States under a \"D-1\" conditional landing permit (granting an alien crewman temporary shore leave while his ship is in port), appeared on January 6, 1965, at the Portland, Oregon, office of the Immigration and Naturalization Service (INS) and claimed that he feared persecution upon return to Yugoslavia. On the basis of his statement that he would not return to his …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"8","1":"5"}},{"t":"case","label":"Johnson v. Robison","cite":"415 U.S. 361","y":1974,"id":"1973/72-1297","sc":1,"sum":"Appellee, who had been exempted from military service as a Class 1-0 conscientious objector bo. who perfurmed required alternative civilian service, after being denied educational benefits under the Veterans' Readjustmcnt Benefits Act of 1966 brought this class action for a declaratory judgment that' the provisions of the Act making him and his class ineligible for such benefits violated the First Amendment's …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"60"}},{"t":"case","label":"Kennedy v. Plan Adm’r for DuPont Sav. & Inv. Plan","cite":"555 U.S. 285","y":2009,"id":"2008/07-636","sc":1,"sum":"The Court held that the Employee Retirement Income Security Act's anti-alienation provision nonetheless recognizes a wavier which holds that a spouse's right to the other spouse's pension benefits is void upon divorce.","sumSrc":"Oyez","by":{"0":"9, 30, 31","1":"31"}},{"t":"case","label":"Lawrence v. Texas","cite":"539 U.S. 558","y":2003,"id":"2002/02-102","sc":1,"op":1,"sum":"The Court found that a Texas statute banning consenting homosexual adults from engaging in sexual acts violated the Fourteenth Amendment's guarantee of equal protection.","sumSrc":"Oyez","by":{"0":"51, 53"}},{"t":"case","label":"Long Island Care at Home, Ltd. v. Coke","cite":"551 U.S. 158","y":2007,"id":"2006/06-593","sc":1,"op":4,"sum":"A unanimous Court ruled that the Department of Labor's regulation was \"valid and binding\" and therefore entitled to all of the deference courts normally give to administrative regulations. The opinion by Justice Stephen Breyer considered the regulation a normal instance of an agency \"filling a statutory gap,\" and rejected each of the lower court's arguments that it was unlawful.","sumSrc":"Oyez","by":{"0":"9, 30, 31, 51","1":"6, 19, 31, 38, 42","2":"16"}},{"t":"case","label":"Lyng v. Payne","cite":"476 U.S. 926","y":1986,"id":"1985/84-1948","sc":1,"op":2,"sum":"Under the Consolidated Farm and Rural Development Act, the Secretary of Agriculture has authority to make emergency loans to farmers who suffer economic losses as a result of a natural disaster. Pursuant to a rule of the Farmers Home Administration (FmHA), the Secretary required loan applicants suffering from disasters occurring between December 26, 1972, and April 20, 1973, to file their applications by April 2, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"8","1":"5"}},{"t":"case","label":"Martin v. Occupational Safety & Health Review Comm’n","cite":"499 U.S. 144","y":1991,"id":"1990/89-1541","sc":1,"op":7,"sum":"A reviewing court should defer to the Secretary when the Secretary and the Commission furnish reasonable but conflicting interpretations of an ambiguous regulation promulgated by the Secretary under the Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4, 34, 41","1":"15, 20, 21, 29, 33, 45","2":"4"}},{"t":"case","label":"Mastrobuono v. Shearson Lehman Hutton, Inc.","cite":"514 U.S. 52","y":1995,"id":"1994/94-18","sc":1,"op":1,"sum":"The arbitral award should have been enforced as within the scope of the contract between the parties.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"60"}},{"t":"case","label":"Metropolitan Wash. Airports Auth. v. Citizens for Abatement of Aircraft Noise, Inc.","cite":"501 U.S. 252","y":1991,"id":"1990/90-906","sc":1,"op":1,"sum":"An Act of Congress (hereinafter the Transfer Act) authorized the transfer of operating control of Washington National Airport (National) and Dulles International Airport (Dulles) from the federal Department of Transportation to petitioner Metropolitan Washington Airports Authority (MWAA), which was created by a compact between Virginia and the District of Columbia. Both airports are located in the Virginia suburbs …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45"}},{"t":"case","label":"Motor Vehicle Mfrs. Ass’n of U.S., Inc. v. State Farm Mut. Auto. Ins. Co.","cite":"463 U.S. 29","y":1983,"id":"1982/82-354","sc":1,"op":1,"sum":"The Supreme Court held that the rescission of a standard should be reviewed based on whether the decision was arbitrary or capricious. Because the removal of a standard often entails the same level of policy changes as the promulgation of a law, it should be reviewed under the same tests.","sumSrc":"Oyez","by":{"0":"28, 30"}},{"t":"case","label":"National Cable & Telecomms. Ass’n v. Brand X Internet Servs.","cite":"545 U.S. 967","y":2005,"id":"2004/04-277","sc":1,"op":1,"sum":"The Court held that the FCC lawfully construed the Communications Act to not define cable broadband providers as \"telecommunications services.\" The Court held that the Ninth Circuit should have followed the Supreme Court's 1984 decision in Chevron v. Natural Resources Defense Council.","sumSrc":"Oyez","by":{"0":"33","1":"20, 33"}},{"t":"case","label":"National Family Planning & Reprod. Health Ass’n, Inc. v. Sullivan","cite":"979 F.2d 227","y":1992,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/979/227/","by":{"0":"36"}},{"t":"case","label":"National Fuel Gas Supply Corp. v. FERC","cite":"811 F.2d 1563","y":1987,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/811/1563/","by":{"0":"40"}},{"t":"case","label":"North Carolina Growers’ Ass’n, Inc. v. United Farm Workers","cite":"702 F.3d 755","y":2012,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/702/755/","op":2,"by":{"0":"39, 52"}},{"t":"case","label":"Patterson v. McLean Credit Union","cite":"491 U.S. 164","y":1989,"id":"scdb/1988-115","sc":1,"op":4,"sum":"Stating that when that is so, “[c]onsiderations of stare decisis have special force”.","sumSrc":"opinion","by":{"0":"47, 48","1":"35, 44"}},{"t":"case","label":"Payne v. Tennessee","cite":"501 U.S. 808","y":1991,"id":"1990/90-5721","sc":1,"op":2,"sum":"The Court reasoned that since \"[v]irtually no limits are placed on the relevant mitigating evidence a capital defendant may introduce concerning his own circumstances,\" the prosecution must be allowed to submit similar counter evidence.","sumSrc":"Oyez","by":{"0":"47, 49","1":"35, 36, 37"}},{"t":"case","label":"Pearson v. Callahan","cite":"555 U.S. 223","y":2009,"id":"2008/07-751","sc":1,"op":1,"ar":1,"sum":"A case in which the Court overturned its previous decision in Saucier v. Katz, which prescribed a rigid test for government qualified immunity claims, and held that inquiries should be at the discretion of the lower courts.","sumSrc":"Oyez","by":{"0":"47, 48, 49, 51","1":"37","2":"13"}},{"t":"case","label":"Perez v. Mortgage Bankers Ass’n","cite":"135 S. Ct. 1199","y":2015,"id":"2014/13-1041","sc":1,"op":10,"ar":2,"sum":"The Court ruled that federal agencies do not need to engage in a notice-and-comment procedure before significantly altering an interpretation of a rule of agency regulation.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"2, 3, 7, 9"}},{"t":"case","label":"PLIVA, Inc. v. Mensing","cite":"564 U.S. 604","y":2011,"id":"2010/09-993","sc":1,"op":2,"sum":"The Court held that generic drug makers cannot be sued for not warning about potentially dangerous side effects on their drug labels, even when they follow federal rules that only require their labels to match those of their brand-name equivalents.","sumSrc":"Oyez","by":{"0":"9","1":"6, 38"}},{"t":"case","label":"Reno v. Bossier Par. Sch. Bd.","cite":"520 U.S. 471","y":1997,"id":"1996/95-1455","sc":1,"sum":"The Court ruled that preclearance under ?5 of the Voting Rights Act of 1965 may not be denied solely on the basis that a covered jurisdiction's new voting \"standard, practice, or procedure\" violates ? 2 of the Act.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Robertson v. Methow Valley Citizens Council","cite":"490 U.S. 332","y":1989,"id":"1988/87-1703","sc":1,"op":1,"sum":"The Forest Service is authorized by statute to manage national forests for, inter alia, recreational purposes. Because its decision to issue a recreational special use permit is a \"major Federal action\" within the meaning of the National Environmental Policy Act of 1969 (NEPA), that decision must be preceded by the preparation of an Environmental Impact Statement (EIS). After a Service study designated a particular …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"8","1":"5, 25"}},{"t":"case","label":"Rust v. Sullivan","cite":"500 U.S. 173","y":1991,"id":"1990/89-1391","sc":1,"sum":"The Court held that the \"regulations promulgated by the Secretary [of HHS] do not raise the sort of 'grave and doubtful constitutional questions' that would lead us to assume Congress did not intend to authorize their issuance.\" Should government subsidize one protected right (family planning), as it does in this case, it does not follow that government must subsidize analogous counterpart rights (abortion services).","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"Saucier v. Katz","cite":"533 U.S. 194","y":2001,"id":"2000/99-1977","sc":1,"op":4,"sum":"The Court held that \"the ruling on qualified immunity requires an analysis not susceptible of fusion with the question whether unreasonable force was used in making the arrest.\" \"The approach the Court of Appeals adopted -- to deny summary judgment any time a material issue of fact remains on the excessive force claim -- could undermine the goal of qualified immunity to 'avoid excessive disruption of government and permit the resolution of many insubstantial claims on summary judgment,'\" wrote Justice Kennedy.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"Shalala v. Guernsey Mem’l Hosp.","cite":"514 U.S. 87","y":1995,"id":"1994/93-1251","sc":1,"op":2,"sum":"After the refinancing of its bonded debt resulted in a \"defeasance\" loss for accounting purposes, respondent health care provider (hereinafter Hospital) determined that it was entitled to Medicare reimbursement for part of that loss. Although the Hospital contended that it should receive its full reimbursement in the year of the refinancing, the fiscal intermediary agreed with petitioner Secretary of Health and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31, 33","1":"5, 23, 43"}},{"t":"case","label":"Skidmore v. Swift & Co.","cite":"323 U.S. 134","y":1944,"id":"1940-1955/12","sc":1,"op":17,"ar":7,"sum":"The Court held that there was no reason that time spent waiting could not also be time spent working, especially in cases in which the conditions of employment involve waiting time. Although it can be difficult to determine the facts of a case and whether the activity in question constitutes work, Congress granted the courts the authority to do so.","sumSrc":"Oyez","by":{"0":"7, 43","1":"16, 28, 33","2":"11"}},{"t":"case","label":"Smiley v. Citibank (S.D.), N.A.","cite":"517 U.S. 735","y":1996,"id":"1995/95-860","sc":1,"sum":"The Court held that the National Bank Act of 1864 authorizes such charges because a regulation adopted by the Comptroller of the Currency, which defined interest to include late-payment fees, was a reasonable interpretation of the act and entitled to deference.","sumSrc":"Oyez","by":{"0":"29","1":"20"}},{"t":"case","label":"South Dakota v. Wayfair, Inc.","cite":"138 S. Ct. 2080","y":2018,"id":"2017/17-494","sc":1,"op":2,"sum":"A case in which the Court overruled Quill Corp. v. North Dakota and National Bellas Hess, Inc. v. Department of Revenue of Illinois, holding that states may require sellers with no physical presence in the state to collect and remit sales tax for goods sold within the state.","sumSrc":"Oyez","by":{"0":"47, 51, 52, 53"}},{"t":"case","label":"Southern Goods Corp. v. Bowles","cite":"158 F.2d 587","y":1946,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/158/587/","op":1,"by":{"0":"7"}},{"t":"case","label":"Stinson v. United States","cite":"508 U.S. 36","y":1993,"id":"1992/91-8685","sc":1,"op":1,"sum":"After petitioner Stinson pleaded guilty to a five-count indictment resulting from his robbery of a bank, the District Court sentenced him as a career offender under United States Sentencing Commission, Guidelines Manual §4B1.1, which requires, inter alia,that \"the instant offense of conviction [be] a crime of violence.\" The court found that Stinson's offense of possession of a firearm by a convicted felon, 18 U. S. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"8","1":"5"}},{"t":"case","label":"Talk Am., Inc. v. Michigan Bell Tel. Co.","cite":"564 U.S. 50","y":2011,"id":"2010/10-313","sc":1,"op":3,"sum":"The Court held that federal law requires local telephone companies to allow new competitors in their markets to link to their existing networks through connecting wires at low, government-regulated rates.","sumSrc":"Oyez","by":{"0":"37, 38, 45, 53"}},{"t":"case","label":"Thomas Jefferson Univ. v. Shalala","cite":"512 U.S. 504","y":1994,"id":"1993/93-120","sc":1,"op":7,"sum":"The Secretary's interpretation of the anti-redistribution principle is reasonable. Because its application suffices to deny reimbursement of the disputed costs in this case, there is no need to decide the validity of the Secretary's interpretation of the community support language.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"8, 37, 41, 43","1":"passim"}},{"t":"case","label":"Thorpe v. Housing Auth. of City of Durham","cite":"393 U.S. 268","y":1969,"id":"1968/20","sc":1,"op":2,"sum":"The Court also decided that the circular was mandatory, not advisory, and it was not an unconstitutional impairment of the Housing Authorities lease agreement. Justice Hugo L. Black wrote a special concurrence stating that because the Housing Authority admitted to following the circular nothing needed to be decided other than that the circular applied in this case.","sumSrc":"Oyez","by":{"0":"7, 29, 51","1":"4"}},{"t":"case","label":"Udall v. Tallman","cite":"380 U.S. 1","y":1965,"id":"1964/34","sc":1,"op":2,"sum":"Since their promulgation, the Secretary of the Interior has consistently construed Executive Order No. 8979 and Public Land Order No. 487, relating to the disposition of public lands located in the Kenai National Moose Range in Alaska, not to bar the issuance of oil and gas leases. His interpretation has been made a repeated matter of public record, and a number of leases have been developed, at great expense, in …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"7","1":"4"}},{"t":"case","label":"United States v. Gaudin","cite":"515 U.S. 506","y":1995,"id":"1994/94-514","sc":1,"sum":"The trial judge's refusal to submit the question of \"materiality\" to the jury was unconstitutional.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"49"}},{"t":"case","label":"United States v. Larionoff","cite":"431 U.S. 864","y":1977,"id":"1976/76-413","sc":1,"op":2,"sum":"Stating that the Court “need not tarry” over the regulation’s language given Seminole Rock.","sumSrc":"opinion","by":{"0":"8","1":"4, 27, 29"}},{"t":"case","label":"United States v. Mead Corp.","cite":"533 U.S. 218","y":2001,"id":"2000/99-1434","sc":1,"op":5,"ar":4,"sum":"The Court held that the \"administrative implementation of a particular statutory provision qualifies for [the greatest level of deference accorded under Chevron U.S.A. Inc. v. Natural Resources Defense Council] when it appears that Congress delegated authority to the agency generally to make rules carrying the force of law, and that the agency interpretation claiming deference was promulgated in the exercise of that authority.\" Justice Souter wrote that \"a tariff classification has no claim to judicial deference under Chevron, there being no indication that Congress intended such a ruling to carry the force of law, but we hold that under Skidmore v. Swift & Co., the ruling is eligible to claim respect according to its persuasiveness.\".","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim"}},{"t":"case","label":"United States v. Morton Salt Co.","cite":"338 U.S. 632","y":1950,"id":"scdb/1949-040","sc":1,"sum":"Under § 5 of the Federal Trade Commission Act, the Commission ordered respondent corporations and others to cease and desist from certain trade practices. The Court of Appeals affirmed the order with modifications and commanded compliance. The decree directed that reports of compliance be filed with the Commission within 90 days, reserved jurisdiction to enter further orders to enforce compliance, and provided that …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26, 28"}},{"t":"case","label":"United States v. Price","cite":"361 U.S. 304","y":1960,"id":"1959/48","sc":1,"sum":"Under § 272 (a) (1) of the Internal Revenue Code of 1939, as amended, failure of the Commissioner of Internal Revenue to send to a taxpayer a 90-day notice of a deficiency in his income tax return does not bar an action by the United States to collect such deficiency and statutory interest thereon when the taxpayer had executed and filed, under § 272 (d), a waiver of the restrictions of § 272 (a) on the assessment …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42"}},{"t":"case","label":"United States v. Seckinger","cite":"397 U.S. 203","y":1970,"id":"1969/395","sc":1,"sum":"Though the Government under the contract clause involved here cannot recover for its own negligence, it is entitled to indemnity on a comparative basis to the extent that it can prove that respondent's negligence contributed to the employee's injuries. Pp. 209-217. 408 F. 2d 146, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"61"}},{"t":"case","label":"United States v. Swank","cite":"451 U.S. 571","y":1981,"id":"1980/79-1515","sc":1,"sum":"The \"percentage depletion\" allowance under §§ 611 and 613 of the Internal Revenue Code of 1954-whereby the owner of an economic interest in a mineral deposit is allowed a special deduction from taxable income measured by a percentage of his gross income derived from exhaustion of the mineral-may not be denied to respondent lessees of underground coal who had the right to extract and sell the coal at prices fixed by …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"8"}},{"t":"case","label":"Williamson v. Mazda Motor of Am., Inc.","cite":"562 U.S. 323","y":2011,"id":"2010/08-1314","sc":1,"sum":"The Court held that a wrongful death lawsuit under California law alleging that Mazda should have installed belt and shoulder seatbelts in the backseat of a minivan is not preempted by a federal regulation that gives automakers the option to install either kind of seatbelts.","sumSrc":"Oyez","by":{"0":"9"}},{"t":"case","label":"Wisconsin Cent. Ltd. v. United States","cite":"138 S. Ct. 2067","y":2018,"id":"2017/17-530","sc":1,"sum":"The Court decided that employee stock options are not taxable “compensation” under the Railroad Retirement Tax Act because they are not “money remuneration.”","sumSrc":"Oyez","by":{"0":"58"}},{"t":"case","label":"Zivotofsky ex rel. Zivotofsky v. Clinton","cite":"566 U.S. 189","y":2012,"id":"2011/10-699","sc":1,"sum":"The Court held that a dispute over passport regulation was not a political issue and is thus liable for judicial review.","sumSrc":"Oyez","by":{"0":"55"}},{"t":"usc","label":"5 U.S.C. § 553","url":"https://www.law.cornell.edu/uscode/text/5/553","subs":["(b)","(b)(A)","(c)"],"stext":{"head":"§553. Rule making","paras":[[0,"(a) This section applies, according to the provisions thereof, except to the extent that there is involved—"],[1,"(1) a military or foreign affairs function of the United States; or"],[1,"(2) a matter relating to agency management or personnel or to public property, loans, grants, benefits, or contracts."],[0,"(b) General notice of proposed rule making shall be published in the Federal Register, unless persons subject thereto are named and either personally served or otherwise have actual notice thereof in accordance with law. The notice shall include—"],[1,"(1) a statement of the time, place, and nature of public rule making proceedings;"],[1,"(2) reference to the legal authority under which the rule is proposed;"],[1,"(3) either the terms or substance of the proposed rule or a description of the subjects and issues involved; and"],[1,"(4) the Internet address of a summary of not more than 100 words in length of the proposed rule, in plain language, that shall be posted on the Internet website under section 206(d) of the E-Government Act of 2002 (44 U.S.C. 3501 note) (commonly known as regulations.gov)."],[0,"Except when notice or hearing is required by statute, this subsection does not apply—"],[1,"(A) to interpretative rules, general statements of policy, or rules of agency organization, procedure, or practice; or"],[1,"(B) when the agency for good cause finds (and incorporates the finding and a brief statement of reasons therefor in the rules issued) that notice and public procedure thereon are impracticable, unnecessary, or contrary to the public interest."],[0,"(c) After notice required by this section, the agency shall give interested persons an opportunity to participate in the rule making through submission of written data, views, or arguments with or without opportunity for oral presentation. After consideration of the relevant matter presented, the agency shall incorporate in the rules adopted a concise general statement of their basis and purpose. When rules are required by statute to be made on the record after opportunity for an agency hearing, sections 556 and 557 of this title apply instead of this subsection."],[0,"(d) The required publication or service of a substantive rule shall be made not less than 30 days before its effective date, except—"],[1,"(1) a substantive rule which grants or recognizes an exemption or relieves a restriction;"],[1,"(2) interpretative rules and statements of policy; or"],[1,"(3) as otherwise provided by the agency for good cause found and published with the rule."],[0,"(e) Each agency shall give an interested person the right to petition for the issuance, amendment, or repeal of a rule."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/553?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§553. Rule making","tname":"Government Organization and Employees","by":{"0":"28, 36","1":"23, 23, 23"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"38 U.S.C. § 501","url":"https://www.law.cornell.edu/uscode/text/38/501","subs":["(a)(1)"],"stext":{"head":"§501. Rules and regulations","paras":[[0,"(a) The Secretary has authority to prescribe all rules and regulations which are necessary or appropriate to carry out the laws administered by the Department and are consistent with those laws, including—"],[1,"(1) regulations with respect to the nature and extent of proof and evidence and the method of taking and furnishing them in order to establish the right to benefits under such laws;"],[1,"(2) the forms of application by claimants under such laws;"],[1,"(3) the methods of making investigations and medical examinations; and"],[1,"(4) the manner and form of adjudications and awards."],[0,"(b) Any rule, regulation, guideline, or other published interpretation or order (and any amendment thereto) issued pursuant to the authority granted by this section or any other provision of this title shall contain citations to the particular section or sections of statutory law or other legal authority upon which such issuance is based. The citation to the authority shall appear immediately following each substantive provision of the issuance."],[0,"(c) In applying section 552(a)(1) of title 5 to the Department, the Secretary shall ensure that subparagraphs (C), (D), and (E) of that section are complied with, particularly with respect to opinions and interpretations of the General Counsel."],[0,"(d) The provisions of section 553 of title 5 shall apply, without regard to subsection (a)(2) of that section, to matters relating to loans, grants, or benefits under a law administered by the Secretary."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/501?type=usc&year=mostrecent&link-type=html"},"head":"§501. Rules and regulations","tname":"Veterans' Benefits","by":{"0":"10, 35","1":"36"}},{"t":"reg","label":"38 C.F.R. § 3.4","url":"https://www.ecfr.gov/current/title-38/section-3.4","by":{"0":"11"}},{"t":"rule","label":"Fed. R. Evid. 401","url":"https://www.law.cornell.edu/rules/fre/rule_401","by":{"0":"57","2":"19, 21"}},{"t":"law","label":"Pub. L. No. 106-475","url":"https://www.govinfo.gov/link/plaw/106/public/475","by":{"0":"59"}},{"t":"reg","label":"70 Fed. Reg. 35,388","url":"https://www.govinfo.gov/link/fr/70/35388","by":{"0":"36, 37, 57"}},{"t":"reg","label":"71 Fed. Reg. 52,455","url":"https://www.govinfo.gov/link/fr/71/52455","by":{"0":"59, 60","2":"5, 18"}},{"t":"case","label":"AT&T Co. v. United States","cite":"299 U.S. 232","y":1936,"id":"scdb/1936-040","sc":1,"sum":"(1) That, in the light of administrative construction, the regulation does not mean that the differences entered in the Adjustment Account must be written off completely; on the contrary, amounts in the Adjustment Account which represent investment by the accounting company in assets of continuing value are to be retained in the account until such assets cease to exist or are retired, and provision is to be made for …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16"}},{"t":"case","label":"Actavis Elizabeth LLC v. United States FDA","cite":"625 F.3d 760","y":2010,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/625/760/","op":1,"by":{"1":"42"}},{"t":"case","label":"Arizona v. Gant","cite":"556 U.S. 332","y":2009,"id":"2008/07-542","sc":1,"op":2,"sum":"The Court held that police may search a suspect's vehicle after his arrest only if it is reasonable to believe that the arrestee might access the vehicle at the time of the search or that the vehicle contains evidence of the offense of the arrest.","sumSrc":"Oyez","by":{"1":"39"}},{"t":"case","label":"Blanding v. DuBose","cite":"454 U.S. 393","y":1982,"id":"1981/81-325","sc":1,"op":1,"sum":"The 1979 letter was a reconsideration request, not a preclearance submission. Because the 1978 referendum did no more than endorse an election method that previously had been submitted to the Attorney General and that was the subject of an outstanding objection, the letter did not amount to a new preclearance submission. It was nothing more than a request that the Attorney General reconsider his earlier objection in …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"5"}},{"t":"case","label":"Blubaugh v. McDonald","cite":"773 F.3d 1310","y":2014,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/773/1310/","by":{"1":"48, 50"}},{"t":"case","label":"Bowen v. Georgetown Univ. Hosp.","cite":"488 U.S. 204","y":1988,"id":"1988/87-1097","sc":1,"op":3,"sum":"Under the Medicare program, the Government reimburses health care providers for expenses incurred in providing medical services to Medicare beneficiaries. The Medicare Act in 42 U. S. C. § 1395x(v)(1)(A) authorizes the Secretary of Health and Human Services (Secretary) to promulgate cost-reimbursement regulations and also provides that \"[s]uch regulations shall... (ii) provide for the making of suitable retroactive …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30"}},{"t":"case","label":"Bowsher v. Synar","cite":"478 U.S. 714","y":1986,"id":"1985/85-1377","sc":1,"sum":"The Court found that the duties which the Congress delegated to the Comptroller General did violate the doctrine of separation of powers and were unconstitutional. A two step process led Chief Justice Burger to arrive at this conclusion.","sumSrc":"Oyez","by":{"1":"45"}},{"t":"case","label":"Capital Network Sys., Inc. v. FCC","cite":"28 F.3d 201","y":1994,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/28/201/","by":{"1":"29"}},{"t":"case","label":"Christensen v. Harris Cnty.","cite":"529 U.S. 576","y":2000,"id":"1999/98-1167","sc":1,"op":2,"sum":"The Court held 6-3 that \"[n]othing in the FLSA or its implementing regulations prohibits a public employer from compelling the use of compensatory time.\" Justice Thomas wrote for the Court that, \"under the FLSA, an employer is free to require an employee to take time off work, and an employer is also free to use the money it would have paid in wages to cash out accrued compensatory time.","sumSrc":"Oyez","by":{"1":"15, 28"}},{"t":"case","label":"Citizens United v. FEC","cite":"558 U.S. 310","y":2010,"id":"2008/08-205","sc":1,"sum":"The Court held that corporate funding of independent political broadcasts in elections cannot be limited under the First Amendment.","sumSrc":"Oyez","by":{"1":"39"}},{"t":"case","label":"FCC v. Pottsville Broad. Co.","cite":"309 U.S. 134","y":1940,"id":"scdb/1939-099","sc":1,"sum":"1. A lower court's interpretation of its own mandate does not bind this Court.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16, 17"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"op":1,"sum":"The Court held that \"Congress has not given the FDA the authority to regulate tobacco products as customarily marketed.\" The ruling was based on the FDCA as a whole and in conjunction with Congress' subsequent tobacco-specific legislation. \"By no means do we question the seriousness of the problem that the FDA has sought to address,\" Justice O'Connor wrote for the majority.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"FTC v. Cement Inst.","cite":"333 U.S. 683","y":1948,"id":"scdb/1947-067","sc":1,"op":1,"sum":"L The Commission has jurisdiction to conclude that conduct tending to restrain trade is an unfair method of competition viola-tive of § 5 of the Federal Trade Commission Act, even though the selfsame conduct may also violate the Sherman Act. Pp. 689-693. Cement Co. et al.; No. 25, Federal Trade Comm'n v. Marquette Cement Mig. Co.; No. 26, Federal Trade Comm'n v. Calaveras Cement Co. et al..N;o. 27, Federal Trade …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"46"}},{"t":"case","label":"Fidelity Fed. Sav. & Loan Ass’n v. de la Cuesta","cite":"458 U.S. 141","y":1982,"id":"1981/81-750","sc":1,"op":1,"sum":"The Board's due-on-sale regulation pre-empts conflicting state limitations on the due-on-sale practices of federal savings and loan associations, and thus bars application of the Wellenkamp rule to such associations.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"5"}},{"t":"case","label":"Ford Motor Credit Co. v. Milhollin","cite":"444 U.S. 555","y":1980,"id":"1979/78-1487","sc":1,"op":4,"sum":"TILA does not mandate a general rule of disclosure for acceleration clauses.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"5, 21, 41, 43"}},{"t":"case","label":"Gardebring v. Jenkins","cite":"485 U.S. 415","y":1988,"id":"1987/86-978","sc":1,"sum":"The federal notice regulation was not violated by the Department. Pursuant to the regulation, the Department has distributed two printed brochures that generally describe the AFDC program and the recipient's duty to report all household income monthly. When the 1981 amendment was enacted, the Department sent a letter to all AFDC recipients advising them of the major changes in the program and alerting them to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"4, 15"}},{"t":"case","label":"Global Tel*Link v. FCC","cite":"866 F.3d 397","y":2017,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/866/397/","by":{"1":"29"}},{"t":"case","label":"Halliburton Co. v. Erica P. John Fund, Inc.","cite":"573 U.S. 258","y":2014,"id":"2013/13-317","sc":1,"op":2,"sum":"The Court held that there is no undue burden in allowing defendants in securities fraud cases from presenting evidence regarding the alleged impact of the misinformation on stock prices.","sumSrc":"Oyez","by":{"1":"44"}},{"t":"case","label":"Henry Schein, Inc. v. Archer & White Sales, Inc.","cite":"139 S. Ct. 524","y":2019,"id":"2018/17-1272","sc":1,"op":1,"sum":"The “wholly groundless” exception to the general rule that courts must enforce contracts that delegate threshold arbitrability questions to an arbitrator, not a court, is inconsistent with the Federal Arbitration Act and this Court’s precedent.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"41","2":"10"}},{"t":"case","label":"INS v. National Ctr. for Immigrants’ Rights, Inc.","cite":"502 U.S. 183","y":1991,"id":"1991/90-1090","sc":1,"op":1,"sum":"The regulation on its face is consistent with the Attorney General's statutory authority.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"5, 31"}},{"t":"case","label":"Jicarilla Apache Tribe v. FERC","cite":"578 F.2d 289","y":1978,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/578/289/","op":1,"by":{"1":"34"}},{"t":"case","label":"M. Kraus & Bros., Inc. v. United States","cite":"327 U.S. 614","y":1946,"id":"scdb/1945-045","sc":1,"sum":"1. Section 1429.5 of Revised Maximum Price Regulation No. 269 (issued December 18, 1942, under the Emergency Price Control Act)-which provides that the price limitations on poultry prescribed by the regulation shall not be evaded by any method, direct or indirect, whether in connection with any offer or sale of a priceregulated commodity alone \"or in conjunction with any other commodity,\" or by way of any trade …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"17"}},{"t":"case","label":"Maine Med. Ctr. v. Burwell","cite":"775 F.3d 470","y":2015,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/775/470/","by":{"1":"31"}},{"t":"case","label":"Marcello v. Bonds","cite":"349 U.S. 302","y":1955,"id":"scdb/1954-086","sc":1,"sum":"After a hearing pursuant to § 242 (b) of the Immigration and Nationality Act of 1952, petitioner, an alien who had been convicted in 1938 of violation of the Marihuana Tax Act, was ordered deported. Section 241 (a) (11) of the 1952 Act makes such conviction at any time ground for deportation, and § 241 (d) provides that the deportation prdvisions of § 241 (a) shall apply even though the facts giving rise to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"46"}},{"t":"case","label":"Maryland Gen. Hosp., Inc. v. Thompson","cite":"308 F.3d 340","y":2002,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/308/340/","sum":"Rejecting an agency’s interpretation of a Medicare reimbursement regulation, to which other courts had deferred, as inconsistent with the plain meaning of the regulation.","sumSrc":"brief:1","by":{"1":"26"}},{"t":"case","label":"McMunn v. Babcock & Wilcox Power Generation Grp., Inc.","cite":"869 F.3d 246","y":2017,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/869/246/","op":1,"by":{"1":"43"}},{"t":"case","label":"Michigan v. Bay Mills Indian Cmty.","cite":"572 U.S. 782","y":2014,"id":"2013/12-515","sc":1,"op":4,"sum":"The Court held that Indian tribes have sovereign immunity that can only be revoked by Congress, and that the immunity extends to their commercial activities, even if they are not on their protected land.","sumSrc":"Oyez","by":{"1":"35, 37"}},{"t":"case","label":"Mullins Coal Co. v. Director, Officer of Workers’ Comp. Programs","cite":"484 U.S. 135","y":1987,"id":"1987/86-327","sc":1,"op":2,"sum":"Section 203(a) requires that the claimant establish at least one of the qualifying facts by a preponderance of the evidence.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"5, 18"}},{"t":"case","label":"NLRB v. Bell Aerospace Co.","cite":"416 U.S. 267","y":1974,"id":"1973/72-1598","sc":1,"sum":"On a petition by a labor union for a representation election, the National Labor Relations Board (NLRB) held that the buyers employed by respondent company constituted an appropriate collective-bargaining unit and directed an election. The NLRB stated that even though the buyers might be \"managerial employees\" they were nevprtheless covered by the National Labor Relations Act (NLRA) in the absence of any showing …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25","2":"6"}},{"t":"case","label":"NLRB v. Noel Canning","cite":"134 S. Ct. 2550","y":2014,"url":"https://www.courtlistener.com/c/S.%20Ct./134/2550/","sc":1,"by":{"1":"46"}},{"t":"case","label":"National Ass’n of Mfrs. v. Department of Def.","cite":"138 S. Ct. 617","y":2018,"id":"2017/16-299","sc":1,"sum":"The Court decided that challenges to the Environmental Protection Agency’s rule that defines the scope of United States waters must be filed in federal district courts.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"Negusie v. Holder","cite":"555 U.S. 511","y":2009,"id":"2008/07-499","sc":1,"sum":"The Court held that the Board of Immigration Appeals (BIA) incorrectly interpreted provisions of the Immigration and Nationality Act (INA) from a mistaken legal premise.","sumSrc":"Oyez","by":{"1":"46"}},{"t":"case","label":"Northern Ind. Pub. Serv. Co. v. Porter Cnty. Chapter of the Izaak Walton League of Am., Inc.","cite":"423 U.S. 12","y":1975,"id":"1975/75-4","sc":1,"op":2,"sum":"The Court of Appeals erred in setting aside the Atomic Energy Commission's Licensing and Appeal Boards' approval of a construction permit for a commercial nuclear powered electric generating plant on the ground that the Boards failed to follow the AEC's own regulations governing the minimum allowable \"population center distance\" in nuclear plant siting. Where, even if the meaning is not free from doubt, the AEC's …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"5, 31"}},{"t":"case","label":"Norwegian Nitrogen Prods. Co. v. United States","cite":"288 U.S. 294","y":1933,"id":"scdb/1932-150","sc":1,"sum":"The Tariff Act of 1922 empowers the President to change rates of duty in order to equalize differences in costs of production in this country and abroad, but provides--§ 315 (c)-that before he acts there shall have been an investigation of such differences by the Tariff Commission, in the making of which the Commission shall give reasonable public notice of its hearings, and shall give \"reasonable opportunity to …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16, 32"}},{"t":"case","label":"Pauley v. BethEnergy Mines, Inc.","cite":"501 U.S. 680","y":1991,"id":"1990/89-1714","sc":1,"op":3,"ar":1,"sum":"The third and fourth rebuttal provisions in the DOL regulations do not render those regulations \"more restrictive than\" the HEW regulations.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"28, 40, 42"}},{"t":"case","label":"Pereira v. Sessions","cite":"138 S. Ct. 2105","y":2018,"id":"2017/17-459","sc":1,"op":2,"sum":"The Court held that a notice to appear for a removal hearing that does not specify the place and time of the hearing does not trigger the stop-time rule of 8 U.S.C. § 1229b(b)(1), which gives the attorney general discretion to cancel removal for an alien who, among other criteria, has been continuously physically present in the country for at least ten years.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"Riegel v. Medtronic, Inc.","cite":"552 U.S. 312","y":2008,"id":"2007/06-179","sc":1,"op":1,"sum":"The Court, in an 8-1 decision, affirmed the Second Circuit and granted summary judgment in favor of Medtronic. The Court's opinion, written by Justice Antonin Scalia, noted that the MDA pre-empted state common law claims for defective devices such as this one.","sumSrc":"Oyez","by":{"1":"6"}},{"t":"case","label":"Sears v. Principi","cite":"349 F.3d 1326","y":2003,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/349/1326/","by":{"1":"47"}},{"t":"case","label":"Shinseki v. Sanders","cite":"556 U.S. 396","y":2009,"id":"2008/07-1209","sc":1,"op":1,"sum":"The Court found that the lower court's framework for evaluating VA (Veterans' Affairs) notice errors conflicted with the established law that the Veterans Court \"take due account of the rule of the prejudicial error.\"","sumSrc":"Oyez","by":{"1":"7"}},{"t":"case","label":"Sierra Pac. Power Co. v. United States EPA","cite":"647 F.2d 60","y":1981,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/647/60/","by":{"1":"31"}},{"t":"case","label":"Washington State Dep’t of Soc. & Health Servs. v. Guardianship Estate of Keffeler","cite":"537 U.S. 371","y":2003,"id":"2002/01-1420","sc":1,"op":1,"sum":"The Court held that the state's use of the Social Security benefits to reimburse itself does not violate the Social Security Act's anti-attachment provision.","sumSrc":"Oyez","by":{"1":"6"}},{"t":"const","label":"Article I, Section 1","clauses":[["legislative-vesting","Legislative Vesting Clause"]],"text":"All legislative Powers herein granted shall be vested in a Congress of the United States, which shall consist of a Senate and House of Representatives.","by":{"1":"45"}},{"t":"const","label":"Article II, Section 1, Clause 1","clauses":[["executive-vesting","Executive Vesting Clause"]],"text":"The executive Power shall be vested in a President of the United States of America. He shall hold his Office during the Term of four Years, and, together with the Vice President, chosen for the same Term, be elected, as follows","by":{"1":"45"}},{"t":"const","label":"Article III, Section 1","clauses":[["judicial-vesting","Judicial Vesting Clause"]],"text":"The judicial Power of the United States, shall be vested in one supreme Court, and in such inferior Courts as the Congress may from time to time ordain and establish. The Judges, both of the supreme and inferior Courts, shall hold their Offices during good Behaviour, and shall, at stated Times, receive for their Services, a Compensation, which shall not be diminished during their Continuance in Office.","by":{"1":"46"}},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","subs":["(4)","(7)"],"stext":{"head":"§551. Definitions","paras":[[0,"For the purpose of this subchapter—"],[1,"(1) \"agency\" means each authority of the Government of the United States, whether or not it is within or subject to review by another agency, but does not include—"],[2,"(A) the Congress;"],[2,"(B) the courts of the United States;"],[2,"(C) the governments of the territories or possessions of the United States;"],[2,"(D) the government of the District of Columbia;"],[1,"or except as to the requirements of section 552 of this title—"],[2,"(E) agencies composed of representatives of the parties or of representatives of organizations of the parties to the disputes determined by them;"],[2,"(F) courts martial and military commissions;"],[2,"(G) military authority exercised in the field in time of war or in occupied territory; or"],[2,"(H) functions conferred by sections 1738, 1739, 1743, and 1744 of title 12; subchapter II of chapter 471 of title 49; or sections 1884, 1891–1902, and former section 1641(b)(2), of title 50, appendix; 1"],[1,"(2) \"person\" includes an individual, partnership, corporation, association, or public or private organization other than an agency;"],[1,"(3) \"party\" includes a person or agency named or admitted as a party, or properly seeking and entitled as of right to be admitted as a party, in an agency proceeding, and a person or agency admitted by an agency as a party for limited purposes;"],[1,"(4) \"rule\" means the whole or a part of an agency statement of general or particular applicability and future effect designed to implement, interpret, or prescribe law or policy or describing the organization, procedure, or practice requirements of an agency and includes the approval or prescription for the future of rates, wages, corporate or financial structures or reorganizations thereof, prices, facilities, appliances, services or allowances therefor or of valuations, costs, or accounting, or practices bearing on any of the foregoing;"],[1,"(5) \"rule making\" means agency process for formulating, amending, or repealing a rule;"],[1,"(6) \"order\" means the whole or a part of a final disposition, whether affirmative, negative, injunctive, or declaratory in form, of an agency in a matter other than rule making but including licensing;"],[1,"(7) \"adjudication\" means agency process for the formulation of an order;"],[1,"(8) \"license\" includes the whole or a part of an agency permit, certificate, approval, registration, charter, membership, statutory exemption or other form of permission;"],[1,"(9) \"licensing\" includes agency process respecting the grant, renewal, denial, revocation, suspension, annulment, withdrawal, limitation, amendment, modification, or conditioning of a license;"],[1,"(10) \"sanction\" includes the whole or a part of an agency—"],[2,"(A) prohibition, requirement, limitation, or other condition affecting the freedom of a person;"],[2,"(B) withholding of relief;"],[2,"(C) imposition of penalty or fine;"],[2,"(D) destruction, taking, seizure, or withholding of property;"],[2,"(E) assessment of damages, reimbursement, restitution, compensation, costs, charges, or fees;"],[2,"(F) requirement, revocation, or suspension of a license; or"],[2,"(G) taking other compulsory or restrictive action;"],[1,"(11) \"relief\" includes the whole or a part of an agency—"],[2,"(A) grant of money, assistance, license, authority, exemption, exception, privilege, or remedy;"],[2,"(B) recognition of a claim, right, immunity, privilege, exemption, or exception; or"],[2,"(C) taking of other action on the application or petition of, and beneficial to, a person;"],[1,"(12) \"agency proceeding\" means an agency process as defined by paragraphs (5), (7), and (9) of this section;"],[1,"(13) \"agency action\" includes the whole or a part of an agency rule, order, license, sanction, relief, or the equivalent or denial thereof, or failure to act; and"],[1,"(14) \"ex parte communication\" means an oral or written communication not on the public record with respect to which reasonable prior notice to all parties is not given, but it shall not include requests for status reports on any matter or proceeding covered by this subchapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/551?type=usc&year=mostrecent&link-type=html"},"head":"§551. Definitions","tname":"Government Organization and Employees","by":{"1":"3, 23","2":"2, 5, 2"}},{"t":"usc","label":"5 U.S.C. § 556","url":"https://www.law.cornell.edu/uscode/text/5/556","by":{"1":"23"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","subs":["(2)(A)"],"stext":{"head":"§706. Scope of review","paras":[[0,"To the extent necessary to decision and when presented, the reviewing court shall decide all relevant questions of law, interpret constitutional and statutory provisions, and determine the meaning or applicability of the terms of an agency action. The reviewing court shall—"],[1,"(1) compel agency action unlawfully withheld or unreasonably delayed; and"],[1,"(2) hold unlawful and set aside agency action, findings, and conclusions found to be—"],[2,"(A) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[2,"(B) contrary to constitutional right, power, privilege, or immunity;"],[2,"(C) in excess of statutory jurisdiction, authority, or limitations, or short of statutory right;"],[2,"(D) without observance of procedure required by law;"],[2,"(E) unsupported by substantial evidence in a case subject to sections 556 and 557 of this title or otherwise reviewed on the record of an agency hearing provided by statute; or"],[2,"(F) unwarranted by the facts to the extent that the facts are subject to trial de novo by the reviewing court."],[0,"In making the foregoing determinations, the court shall review the whole record or those parts of it cited by a party, and due account shall be taken of the rule of prejudicial error."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/706?type=usc&year=mostrecent&link-type=html"},"op":21,"head":"§706. Scope of review","tname":"Government Organization and Employees","by":{"1":"36, 36"}},{"t":"usc","label":"29 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/29/201","by":{"1":"5"}},{"t":"usc","label":"29 U.S.C. § 213","url":"https://www.law.cornell.edu/uscode/text/29/213","subs":["(a)(1)"],"by":{"1":"5"}},{"t":"usc","label":"15 U.S.C. § 1601","url":"https://www.law.cornell.edu/uscode/text/15/1601","by":{"1":"38"}},{"t":"usc","label":"15 U.S.C. § 1640","url":"https://www.law.cornell.edu/uscode/text/15/1640","by":{"1":"43"}},{"t":"law","label":"Pub. L. No. 115-55","url":"https://www.govinfo.gov/link/plaw/115/public/55","by":{"1":"8"}},{"t":"usc","label":"15 U.S.C. § 41","url":"https://www.law.cornell.edu/uscode/text/15/41","by":{"1":"45"}},{"t":"usc","label":"15 U.S.C. § 77s-77u","url":"https://www.law.cornell.edu/uscode/text/15/77s-77u","by":{"1":"46"}},{"t":"usc","label":"38 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/38/301","subs":["(b)","(c)(5)"],"by":{"1":"7, 7"}},{"t":"usc","label":"38 U.S.C. § 511","url":"https://www.law.cornell.edu/uscode/text/38/511","subs":["(a)"],"by":{"1":"7"}},{"t":"usc","label":"38 U.S.C. § 1110","url":"https://www.law.cornell.edu/uscode/text/38/1110","by":{"1":"7"}},{"t":"usc","label":"38 U.S.C. § 1131","url":"https://www.law.cornell.edu/uscode/text/38/1131","by":{"1":"7"}},{"t":"usc","label":"38 U.S.C. § 7101","url":"https://www.law.cornell.edu/uscode/text/38/7101","by":{"1":"7"}},{"t":"usc","label":"38 U.S.C. § 7252","url":"https://www.law.cornell.edu/uscode/text/38/7252","by":{"1":"7"}},{"t":"usc","label":"38 U.S.C. § 7266","url":"https://www.law.cornell.edu/uscode/text/38/7266","by":{"1":"7"}},{"t":"usc","label":"38 U.S.C. § 7292","url":"https://www.law.cornell.edu/uscode/text/38/7292","subs":["(a)","(d)(1)"],"stext":{"head":"§7292. Review by United States Court of Appeals for the Federal Circuit","paras":[[0,"(a) After a decision of the United States Court of Appeals for Veterans Claims is entered in a case, any party to the case may obtain a review of the decision with respect to the validity of a decision of the Court on a rule of law or of any statute or regulation (other than a refusal to review the schedule of ratings for disabilities adopted under section 1155 of this title) or any interpretation thereof (other than a determination as to a factual matter) that was relied on by the Court in making the decision. Such a review shall be obtained by filing a notice of appeal with the Court of Appeals for Veterans Claims within the time and in the manner prescribed for appeal to United States courts of appeals from United States district courts."],[0,"(b)(1) When a judge or panel of the Court of Appeals for Veterans Claims, in making an order not otherwise appealable under this section, determines that a controlling question of law is involved with respect to which there is a substantial ground for difference of opinion and that there is in fact a disagreement between the appellant and the Secretary with respect to that question of law and that the ultimate termination of the case may be materially advanced by the immediate consideration of that question, the judge or panel shall notify the chief judge of that determination. Upon receiving such a notification, the chief judge shall certify that such a question is presented, and any party to the case may then petition the Court of Appeals for the Federal Circuit to decide the question. That court may permit an interlocutory appeal to be taken on that question if such a petition is filed with it within 10 days after the certification by the chief judge of the Court of Appeals for Veterans Claims. Neither the application for, nor the granting of, an appeal under this paragraph shall stay proceedings in the Court of Appeals for Veterans Claims, unless a stay is ordered by a judge of the Court of Appeals for Veterans Claims or by the Court of Appeals for the Federal Circuit."],[0,"(2) For purposes of subsections (d) and (e) of this section, an order described in this paragraph shall be treated as a decision of the Court of Appeals for Veterans Claims."],[0,"(c) The United States Court of Appeals for the Federal Circuit shall have exclusive jurisdiction to review and decide any challenge to the validity of any statute or regulation or any interpretation thereof brought under this section, and to interpret constitutional and statutory provisions, to the extent presented and necessary to a decision. The judgment of such court shall be final subject to review by the Supreme Court upon certiorari, in the manner provided in section 1254 of title 28."],[0,"(d)(1) The Court of Appeals for the Federal Circuit shall decide all relevant questions of law, including interpreting constitutional and statutory provisions. The court shall hold unlawful and set aside any regulation or any interpretation thereof (other than a determination as to a factual matter) that was relied upon in the decision of the Court of Appeals for Veterans Claims that the Court of Appeals for the Federal Circuit finds to be—"],[1,"(A) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[1,"(B) contrary to constitutional right, power, privilege, or immunity;"],[1,"(C) in excess of statutory jurisdiction, authority, or limitations, or in violation of a statutory right; or"],[1,"(D) without observance of procedure required by law."],[0,"(2) Except to the extent that an appeal under this chapter presents a constitutional issue, the Court of Appeals may not review (A) a challenge to a factual determination, or (B) a challenge to a law or regulation as applied to the facts of a particular case."],[0,"(e)(1) Upon such review, the Court of Appeals for the Federal Circuit shall have power to affirm or, if the decision of the Court of Appeals for Veterans Claims is not in accordance with law, to modify or reverse the decision of the Court of Appeals for Veterans Claims or to remand the matter, as appropriate."],[0,"(2) Rules for review of decisions of the Court of Appeals for Veterans Claims shall be those prescribed by the Supreme Court under section 2072 of title 28."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/7292?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§7292. Review by United States Court of Appeals for the Federal Circuit","tname":"Veterans' Benefits","by":{"1":"46, 46"}},{"t":"usc","label":"47 U.S.C. § 151","url":"https://www.law.cornell.edu/uscode/text/47/151","by":{"1":"46"}},{"t":"reg","label":"21 C.F.R. § 314.108","url":"https://www.ecfr.gov/current/title-21/section-314.108","subs":["(a)"],"by":{"1":"42"}},{"t":"reg","label":"7 Fed. Reg. 7957","url":"https://www.govinfo.gov/link/fr/7/7957","by":{"1":"2"}},{"t":"reg","label":"84 Fed. Reg. 138","url":"https://www.govinfo.gov/link/fr/84/138","by":{"1":"8"}},{"t":"reg","label":"84 Fed. Reg. 2449","url":"https://www.govinfo.gov/link/fr/84/2449","by":{"1":"8"}},{"t":"case","label":"Accardi v. Shaughnessy","cite":"347 U.S. 260","y":1954,"id":"1940-1955/347us260","sc":1,"sum":"Petitioner is entitled to an opportunity in thp district court to prove the allegation; and, if he does prove it, he should receive a new hearing before the Board without the burden of previous proscription by the list.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"7"}},{"t":"case","label":"Alaska Dep’t of Envtl. Conservation v. EPA","cite":"540 U.S. 461","y":2004,"id":"2003/02-658","sc":1,"sum":"The Court held that the Clean Air Act authorized the EPA to bar the construction of the polluting facility in Alaska. Though Alaska determined the facility's use of \"Low NOx\" met the act's requirement that facilities use \"best available control technology,\" the EPA was reasonable to reject this claim.","sumSrc":"Oyez","by":{"2":"11"}},{"t":"case","label":"Exxon Shipping Co. v. Baker","cite":"554 U.S. 471","y":2008,"id":"2007/07-219","sc":1,"sum":"On the second issue, a 5-4 majority held that judges are free to create remedies in maritime cases where Congress has not legislated in the area. However, this freedom can be lost if Congress passes legislation restraining such judicial activism. Justice David Souter delivered the opinion of the Court.","sumSrc":"Oyez","by":{"2":"13"}},{"t":"case","label":"Federal Express Corp. v. Holowecki","cite":"552 U.S. 389","y":2008,"id":"2007/06-1322","sc":1,"sum":"The Court, in a 7-2 opinion, upheld the Second Circuit, stating that the procedure used to file the document was consistent with the design and purpose of the ADEA.","sumSrc":"Oyez","by":{"2":"11, 12"}},{"t":"case","label":"League of United Latin Am. Citizens v. Perry","cite":"548 U.S. 399","y":2006,"id":"2005/05-204","sc":1,"sum":"The Supreme Court held that the Texas Legislature's redistricting plan did not violate the Constitution, but that part of the plan violated the Voting Rights Act. Justice Anthony Kennedy, writing for a majority of the justices, stated that District 23 had been redrawn in such a way as to deny Latino voters as a group the opportunity to elect a candidate of their choosing, thereby violating the Voting Rights Act.","sumSrc":"Oyez","by":{"2":"19"}},{"t":"case","label":"Lennox v. Principi","cite":"353 F.3d 941","y":2003,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/353/941/","by":{"2":"5"}},{"t":"case","label":"Martinez v. Holder","cite":"740 F.3d 902","y":2014,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/740/902/","by":{"2":"7"}},{"t":"case","label":"Morton v. Ruiz","cite":"415 U.S. 199","y":1974,"id":"1973/72-1052","sc":1,"sum":"Respondent Ruiz and his wife, Papago Indians, left their reservation in Arizona in 1940 to live in an Indian community a few miles away and Ruiz found employment at a nearby mine.. During a prolonged strike, Ruiz applied for but was denied general assistance benefits under the Snyder Act by the Bureau of Indian Affairs (BIA) because of a provision in the BIA Manual limiting eligibility to Indians living \"on …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"5"}},{"t":"case","label":"Nielson v. Shinseki","cite":"607 F.3d 802","y":2010,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/607/802/","by":{"2":"6"}},{"t":"case","label":"NLRB v. Curtin Matheson Sci., Inc.","cite":"494 U.S. 775","y":1990,"id":"1989/88-1685","sc":1,"sum":"The Board acted within its discretion in refusing to adopt a presumption of replacement opposition to the union.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"6"}},{"t":"case","label":"Old Chief v. United States","cite":"519 U.S. 172","y":1997,"id":"1996/95-6556","sc":1,"op":7,"ar":5,"sum":"The Court ruled that a district court abuses its discretion under the Federal Rules of Evidence if it spurns a defendant's offer to concede a prior judgment and admits the full judgment record over the defendant's objection, when the name or nature of the prior offense raises the risk of a verdict tainted by improper considerations, and when the purpose of the evidence is solely to prove the element of prior conviction.","sumSrc":"Oyez","by":{"2":"19"}},{"t":"case","label":"SEC v. Chenery Corp.","cite":"332 U.S. 194","y":1947,"id":"scdb/1946-133","sc":1,"op":1,"sum":"The new order is sustained. Pp. 196-199, 209.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"6"}},{"t":"case","label":"University of Tex. Sw. Med. Ctr. v. Nassar","cite":"570 U.S. 338","y":2013,"id":"2012/12-484","sc":1,"sum":"The Court found that Title VII of the Civil Rights Act of 1964 requires the plaintiff to prove their employer would not have taken an action but for the existence of improper motives.","sumSrc":"Oyez","by":{"2":"11"}},{"t":"usc","label":"29 U.S.C. § 160","url":"https://www.law.cornell.edu/uscode/text/29/160","by":{"2":"6"}},{"t":"usc","label":"38 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/38/101","subs":["(35)"],"by":{"2":"19"}},{"t":"reg","label":"38 C.F.R. § 3.156","url":"https://www.ecfr.gov/current/title-38/section-3.156","subs":["(a)","(c)","(c)(1)","(c)(1)(i)"],"by":{"2":"19, 20, 21, 22, passim, 18, 20, 22"}},{"t":"rule","label":"Fed. R. Evid. 403","url":"https://www.law.cornell.edu/rules/fre/rule_403","by":{"2":"19"}}]};